python3 - <<'EOF'
import re,json
pairs=[('packs/basics','packs/basics/RULES.md',['Calling `Grep` with a context flag','Scheduling a wake-up with the harness','Piping a long command','Killing a process by pattern']),
       ('.claudinite/local/packs/claudinite','.claudinite/local/packs/claudinite/RULES.md',['Reaching for `AskUserQuestion`','Waiting for something to happen','Waiting on GitHub CI or PR check status','A `mcp__github__*` list/search/read call','Making a throwaway probe commit','Re-verifying a branch against a `main` that has moved','Re-applying your edit onto a moved `main`','Syncing local `main`'])]
ids={'Calling `Grep` with a context flag':'grep-context-without-content','Scheduling a wake-up with the harness':'wakeup-without-prompt','Piping a long command':'pipe-tail-hides-exit','Killing a process by pattern':'pkill-pattern-self-match','Reaching for `AskUserQuestion`':'ask-user-question-cost','Waiting for something to happen':'bare-sleep-wait','Waiting on GitHub CI or PR check status':'github-api-via-shell','A `mcp__github__*` list/search/read call':'github-list-without-fields','Making a throwaway probe commit':'commit-all-sweeps-edits','Re-verifying a branch against a `main` that has moved':'merge-main-into-branch','Re-applying your edit onto a moved `main`':'rules-append-only','Syncing local `main`':'git-pull-on-shallow-clone'}
for pack,path,phrases in pairs:
    decl={d['id']:d for d in json.load(open(pack+'/declared-checks.json'))}
    text=open(path).read()
    for block in re.split(r'\n\s*\n', text):
        m=re.match(r'\s*- \*\*(.+?)\*\*', block)
        if not m: continue
        for ph in phrases:
            if m.group(1).startswith(ph):
                d=decl[ids[ph]]
                print('='*100); print('PROSE:', ' '.join(block.split()))
                print('CHECK', d['id'], d['severity'], '| why:', d.get('failureMessage'))
                for g in d.get('guardToolCalls', d.get('forbidRemovedLinesMatching', [])) if isinstance(d.get('guardToolCalls', d.get('forbidRemovedLinesMatching')), list) else [d.get('forbidRemovedLinesMatching')]:
                    print('   what:', g.get('what'), '| fix:', g.get('fix', d.get('fix')))
EOF

python3 - <<'EOF'
p='.claudinite/local/packs/claudinite/test/action-guards.test.mjs'; s=open(p).read()
old="""  // The phrase inside text a command carries — a commit message, a heredoc line
  // mid-sentence — is not the command, and the guard must not read it as one.
"""
new="""  // A Monitor is a shell poll too: the same read through curl or gh, under a different tool.
  const monitor = declaredCheck('.claudinite/local/packs/claudinite', 'github-api-via-shell');
  const polled = makeTranscript([{ type: 'assistant', message: { content: [
    { type: 'tool_use', name: 'Monitor', input: { command: 'while true; do gh pr checks 1; sleep 30; done', description: 'ci', timeout_ms: 1000, persistent: false } },
    { type: 'tool_use', name: 'Monitor', input: { command: 'tail -f run.log', description: 'log', timeout_ms: 1000, persistent: false } },
  ] } }]);
  const root2 = makeRepo({ changed: { 'a.txt': 'x\\n' } });
  try {
    assert.deepEqual(runRule(monitor, buildContext({ root: root2, mode: 'all', transcriptPath: polled.path })).map((f) => f.what), ['a Monitor polling GitHub through the shell: "gh "']);
  } finally { cleanup(root2); polled.cleanup(); }
  // The phrase inside text a command carries — a commit message, a heredoc line
  // mid-sentence — is not the command, and the guard must not read it as one.
"""
assert old in s; open(p,'w').write(s.replace(old,new)); print('monitor case added')
EOF
